  HeadContent,
  Scripts,
} from '@tanstack/react-router'

export const Route = createRootRoute({
  head: () => ({
    meta: [
      {
        charSet: 'utf-8',
      },
      {
        name: 'viewport',
        content: 'width=device-width, initial-scale=1',
      },
      {
        title: 'TanStack AI Chat with Tool Approval',
      },
    ],
  }),
  component: RootComponent,
})

function RootComponent() {
  return (
    <RootDocument>
      <Outlet />
    </RootDocument>
  )
}

function RootDocument({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <html lang="en">
      <head>
        <HeadContent />
        <script src="https://cdn.tailwindcss.com"></script>
      </head>
      <body className="bg-gray-50 min-h-screen">
        {children}
        <Scripts />
      </body>
    </html>
  )
}

import Database from 'better-sqlite3'

let db: any = null

export function getDb() {
  if (!db) {
    db = new Database('notes.db')
    // Create notes table if not exists
    db.prepare(`
      CREATE TABLE IF NOT EXISTS notes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        content TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `).run()
  }
  return db
}

export function createNoteInDb(content: string) {
  const database = getDb()
  const info = database.prepare('INSERT INTO notes (content) VALUES (?)').run(content)
  return { id: info.lastInsertRowid, content }
}

export function getNotesFromDb() {
  const database = getDb()
  return database.prepare('SELECT * FROM notes ORDER BY created_at DESC').all()
}

