import { createServerFn } from '@tanstack/react-start'
import { z } from 'zod'
import { createNoteInDb, getNotesFromDb } from './db'

export const getNotesFn = createServerFn({ method: 'GET' })
  .handler(async () => {
    return getNotesFromDb()
  })

export const createNoteFn = createServerFn({ method: 'POST' })
  .inputValidator(z.object({ content: z.string() }))
  .handler(async ({ data }) => {
    return createNoteInDb(data.content)
  })

import { createFileRoute } from '@tanstack/react-router'
import { streamText, convertToModelMessages } from 'ai'
import { openai } from '@ai-sdk/openai'
import { z } from 'zod'

export const Route = createFileRoute('/api/chat')({
  server: {
    handlers: {
      POST: async ({ request }) => {
        try {
          const { messages } = await request.json()

          const result = streamText({
            model: openai('gpt-4o'),
            messages: convertToModelMessages(messages),
            system: 'You are a helpful assistant. You have access to a createNote tool to save notes to a database. If the user wants to save, write down, or create a note, call the createNote tool with the content of the note. Always explain what you are doing.',
            tools: {
              createNote: {
                description: 'Create a note in the SQLite database.',
                parameters: z.object({
                  content: z.string().describe('The content of the note to be saved to the database'),
                }),
                // We intentionally omit the execute function here so that it pauses on the client
                // for human-in-the-loop approval.
              },
            },
          })

          return result.toUIMessageStreamResponse()
        } catch (error: any) {
          console.error('Error in /api/chat:', error)
          return new Response(JSON.stringify({ error: error.message }), {
            status: 500,
            headers: { 'Content-Type': 'application/json' },
          })
        }
      },
    },
  },
})

import { createFileRoute } from '@tanstack/react-router'
import { useChat } from 'ai/react'
import { useState, useEffect } from 'react'
import { createNoteFn, getNotesFn } from '../lib/notes'

export const Route = createFileRoute('/')({
  component: ChatPage,
})

interface Note {
  id: number
  content: string
  created_at: string
}

function ChatPage() {
  const [notes, setNotes] = useState<Note[]>([])
  const [dbError, setDbError] = useState<string | null>(null)

  // Function to refresh notes from SQLite database
  const refreshNotes = async () => {
    try {
      const data = await getNotesFn()
      setNotes(data as Note[])
      setDbError(null)
    } catch (err: any) {
      console.error('Failed to fetch notes:', err)
      setDbError('Could not load notes from database.')
    }
  }

  // Load notes on mount
  useEffect(() => {
    refreshNotes()
  }, [])

  const { messages, input, handleInputChange, handleSubmit, addToolResult, isLoading } = useChat({
    api: '/api/chat',
    maxSteps: 5,
  })

  return (
    <div className="container mx-auto max-w-6xl p-4 md:p-8 flex flex-col md:flex-row gap-6 h-screen max-h-screen">
      {/* Sidebar - Saved Notes */}
      <div className="w-full md:w-1/3 bg-white border border-gray-200 rounded-xl p-4 flex flex-col h-full overflow-hidden shadow-sm">
        <div className="flex items-center justify-between mb-4 pb-2 border-b border-gray-100">
          <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-indigo-500" viewBox="0 0 20 20" fill="currentColor">
              <path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" />
              <path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" />
            </svg>
            Database Notes ({notes.length})
          </h2>
          <button 
            onClick={refreshNotes}
            className="p-1 text-gray-500 hover:text-indigo-600 hover:bg-indigo-50 rounded transition-colors"
            title="Refresh notes list"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 1121.21 4.75L21.67 4" />
            </svg>
          </button>
        </div>

        {dbError && (
          <div className="bg-red-50 text-red-600 p-2 rounded text-xs mb-3">
            {dbError}
          </div>
        )}

        <div className="flex-1 overflow-y-auto space-y-3 pr-1">
          {notes.length === 0 ? (
            <div className="text-center py-8 text-gray-400 text-sm">
              No notes in notes.db yet. Ask the AI to create one!
            </div>
          ) : (
            notes.map((note) => (
              <div key={note.id} className="bg-gray-50 border border-gray-100 rounded-lg p-3 hover:border-indigo-100 hover:bg-indigo-50/20 transition-all">
                <p className="text-sm text-gray-700 whitespace-pre-wrap break-words">{note.content}</p>
                <div className="mt-2 flex items-center justify-between text-[10px] text-gray-400">
                  <span>ID: {note.id}</span>
                  <span>{new Date(note.created_at).toLocaleString()}</span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Chat Interface */}
      <div className="flex-1 bg-white border border-gray-200 rounded-xl flex flex-col h-full overflow-hidden shadow-sm">
        {/* Chat Header */}
        <div className="bg-indigo-600 text-white p-4 flex items-center gap-3">
          <div className="bg-white/20 p-2 rounded-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <div>
            <h1 className="font-bold text-base md:text-lg">TanStack AI Chat</h1>
            <p className="text-xs text-indigo-100">Gated SQLite Database Writes with User Approval</p>
          </div>
        </div>

        {/* Message List */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
          {messages.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-center p-6">
              <div className="bg-indigo-50 p-4 rounded-full text-indigo-500 mb-3">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                </svg>
              </div>
              <h3 className="text-gray-700 font-semibold mb-1">Start a Conversation</h3>
              <p className="text-gray-500 text-sm max-w-sm">
                Try saying: <span className="font-medium text-indigo-600">"Create a note saying buy groceries at 5 PM"</span> or <span className="font-medium text-indigo-600">"Write down a note about TanStack Start"</span>.
              </p>
            </div>
          )}

          {messages.map((m) => (
            <div key={m.id} className="space-y-2">
              {/* Main Message Bubble */}
              <div className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-2xl px-4 py-2.5 text-sm shadow-sm ${
                  m.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 border border-gray-100 rounded-bl-none'
                }`}>
                  <p className="whitespace-pre-wrap leading-relaxed">{m.content}</p>
                </div>
              </div>

              {/* Tool Invocations inside message */}
              {m.toolInvocations?.map((toolInvocation) => {
                const { toolCallId, toolName, state, args } = toolInvocation

                if (toolName === 'createNote') {
                  if (state === 'call') {
                    return (
                      <div key={toolCallId} className="flex justify-start">
                        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 max-w-[85%] shadow-sm animate-pulse-slow">
                          <div className="flex items-center gap-2 text-amber-800 font-semibold mb-2">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-amber-500" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                            </svg>
                            Approval Required
                          </div>
                          <p className="text-xs text-amber-700 mb-2">The AI is requesting permission to write the following note to the SQLite database:</p>
                          <div className="bg-white/80 border border-amber-100 rounded-lg p-3 text-sm text-gray-700 italic mb-3 whitespace-pre-wrap break-words">
                            "{args.content}"
                          </div>
                          <div className="flex gap-3">
                            <button
                              onClick={async () => {
                                try {
                                  // Call server function to write to SQLite db
                                  await createNoteFn({ data: { content: args.content } })
                                  // Refresh the sidebar notes list
                                  await refreshNotes()
                                  // Resumes the stream with success result
                                  addToolResult({
                                    toolCallId,
                                    result: 'Note successfully created and saved in notes.db.',
                                  })
                                } catch (err: any) {
                                  console.error('Error creating note:', err)
                                  addToolResult({
                                    toolCallId,
                                    result: `Error writing to database: ${err.message}`,
                                  })
                                }
                              }}
                              className="px-4 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-medium transition-colors shadow-sm"
                            >
                              Approve & Write
                            </button>
                            <button
                              onClick={() => {
                                addToolResult({
                                  toolCallId,
                                  result: 'User denied note creation. Note was not saved.',
                                })
                              }}
                              className="px-4 py-1.5 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-xs font-medium transition-colors shadow-sm"
                            >
                              Deny
                            </button>
                          </div>
                        </div>
                      </div>
                    )
                  } else {
                    const approved = !toolInvocation.result.includes('denied') && !toolInvocation.result.includes('Error')
                    return (
                      <div key={toolCallId} className="flex justify-start">
                        <div className={`rounded-xl p-3 max-w-[85%] text-xs border ${
                          approved 
                            ? 'bg-emerald-50 border-emerald-100 text-emerald-800' 
                            : 'bg-rose-50 border-rose-100 text-rose-800'
                        }`}>
                          <div className="flex items-center gap-1.5 font-semibold mb-1">
                            {approved ? (
                              <>
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-emerald-500" viewBox="0 0 20 20" fill="currentColor">
                                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                                </svg>
                                Note Created
                              </>
                            ) : (
                              <>
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-rose-500" viewBox="0 0 20 20" fill="currentColor">
                                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
